action.code:
size_t cell = ckh_isearch(ckh, searchkey);
if (cell == SIZE_T_MAX) {
    return true;
}
ckhc_t *cell_ptr = &ckh->tab[cell];
if (key != nullptr) {
    *key = const_cast<void *>(cell_ptr->key);
}
if (data != nullptr) {
    *data = const_cast<void *>(cell_ptr->data);
}
return false;

